INSERT INTO transportistas(nombre,telefono,activo) VALUES ('Garritas Express','999200001',true),('Mascota Courier Perú','999200002',true) ON CONFLICT(nombre) DO NOTHING;
INSERT INTO zonas(nombre,ciudad,activo) VALUES ('Lima Metropolitana','Lima',true),('Arequipa Urbana','Arequipa',true),('Trujillo Urbana','Trujillo',true),('Cusco Urbana','Cusco',true),('Huancayo Urbana','Huancayo',true) ON CONFLICT(nombre) DO NOTHING;
INSERT INTO coberturas(id_transportista,id_zona,tarifa,dias_estimados,activo) SELECT t.id,z.id,CASE WHEN z.ciudad='Lima' THEN 10.00 ELSE 18.00 END,CASE WHEN z.ciudad='Lima' THEN 1 ELSE 3 END,true FROM transportistas t CROSS JOIN zonas z WHERE t.nombre IN ('Garritas Express','Mascota Courier Perú') AND z.nombre IN ('Lima Metropolitana','Arequipa Urbana','Trujillo Urbana','Cusco Urbana','Huancayo Urbana') ON CONFLICT(id_transportista,id_zona) DO NOTHING;
